// ===== อ่าน PLC Mitsubishi (MC Protocol 3E / Modbus TCP) แบบเชื่อมต่อค้างไว้ =====
// - ต่อ TCP ครั้งเดียวแล้วใช้ซ้ำ (PLC Mitsubishi รับ SLMP ได้ทีละ 1 connection)
// - หลุดเมื่อไหร่ ต่อใหม่เองที่ port เดิม / ค้นหา port ใหม่เฉพาะตอนเริ่มหรือพังนานเกิน 2 นาที
const HOST  = "192.168.0.102";
const PORTS = [502, 5015, 5000, 5001, 5002, 5003, 5004, 5005, 5006, 5007, 5010, 5011, 5012, 1025, 1026, 4999, 8000, 8501, 9600];
const TMO   = 2500;

if (context.get("busy")) return null;
context.set("busy", true);

// ---------- การเชื่อมต่อแบบค้างไว้ ----------
function getConn(port) {
    let c = context.get("conn");
    if (c && c.port === port && !c.dead) return Promise.resolve(c);
    if (c && c.sock) { try { c.sock.destroy(); } catch (e) {} }
    return new Promise(res => {
        const s = new net.Socket();
        c = { port, sock: s, buf: Buffer.alloc(0), wait: null, dead: false, ready: false };
        const kill = (why) => { c.dead = true; c.why = c.why || why; if (c.wait) { const w = c.wait; c.wait = null; w({ err: why }); } };
        s.setNoDelay(true); s.setKeepAlive(true, 10000);
        s.on("data", d => { c.buf = Buffer.concat([c.buf, d]); if (c.wait) c.wait(); });
        s.on("error", e => kill(e.code || e.message));
        s.on("close", () => kill("closed"));
        const t = setTimeout(() => { if (!c.ready) { kill("connect timeout"); s.destroy(); res(c); } }, TMO);
        s.connect(port, HOST, () => { clearTimeout(t); c.ready = true; res(c); });
        context.set("conn", c);
    });
}
function ask(c, frame, need) {
    return new Promise(res => {
        if (c.dead || !c.ready) return res({ err: "ไม่ได้เชื่อมต่อ" });
        c.buf = Buffer.alloc(0);
        const t = setTimeout(() => { c.wait = null; c.dead = true; try { c.sock.destroy(); } catch (e) {} res({ err: "ไม่ตอบ (timeout)" }); }, TMO);
        c.wait = (fail) => {
            if (fail && fail.err) { clearTimeout(t); return res(fail); }
            if (need(c.buf)) { clearTimeout(t); c.wait = null; const b = c.buf; c.buf = Buffer.alloc(0); res({ buf: b }); }
        };
        c.sock.write(frame);
    });
}

// ---------- frame ----------
function mcFrame(start, n) {
    const b = Buffer.alloc(21);
    b.writeUInt16LE(0x0050, 0); b[2] = 0; b[3] = 0xFF; b.writeUInt16LE(0x03FF, 4); b[6] = 0;
    b.writeUInt16LE(12, 7); b.writeUInt16LE(0x0010, 9); b.writeUInt16LE(0x0401, 11); b.writeUInt16LE(0, 13);
    b.writeUIntLE(start, 15, 3); b[18] = 0xA8; b.writeUInt16LE(n, 19); return b;
}
const mcNeed = b => b.length >= 11 && b.length >= 9 + b.readUInt16LE(7);
let tid = 0;
function mbFrame(start, n) { tid = (tid + 1) & 0xFFFF; return Buffer.from([tid >> 8, tid & 255, 0,0, 0,6, 1, 3, start >> 8, start & 255, n >> 8, n & 255]); }
const mbNeed = b => b.length >= 9 && b.length >= 6 + b.readUInt16BE(4);

async function readMC(c) {
    const r = await ask(c, mcFrame(0, 332), mcNeed);
    if (r.err) return r;
    if (r.buf.readUInt16LE(0) !== 0x00D0) return { err: "ไม่ใช่ MC" };
    const end = r.buf.readUInt16LE(9);
    if (end !== 0) return { err: "MC end code 0x" + end.toString(16) };
    const v = []; for (let i = 0; i < 332; i++) v.push(r.buf.readUInt16LE(11 + i * 2)); return { v };
}
async function readMB(c) {
    const v = new Array(332).fill(0);
    for (const [s, n] of [[0, 1], [60, 1], [300, 32]]) {
        const r = await ask(c, mbFrame(s, n), mbNeed);
        if (r.err) return r;
        if (r.buf[7] !== 3) return { err: r.buf[7] === 0x83 ? "Modbus exception " + r.buf[8] : "ไม่ใช่ Modbus" };
        for (let i = 0; i < n; i++) v[s + i] = r.buf.readUInt16BE(9 + i * 2);
    }
    return { v };
}
async function readOnce(cfg) {
    const c = await getConn(cfg.port);
    if (c.dead) return { err: "ต่อ port " + cfg.port + " ไม่ได้ (" + (c.why || "?") + ")" };
    return cfg.proto === "MC" ? readMC(c) : readMB(c);
}

async function discover() {
    const report = [];
    for (const port of PORTS) {
        node.status({ fill: "blue", shape: "ring", text: "กำลังหา... port " + port });
        for (const proto of ["MC", "MB"]) {
            const r = await readOnce({ proto, port });
            if (r.v) { report.push(port + ": " + (proto === "MC" ? "MC Protocol" : "Modbus TCP") + " ✓"); return { cfg: { proto, port }, report, v: r.v }; }
            report.push(port + " " + proto + ": " + r.err);
            const c = context.get("conn"); if (c) { c.dead = true; try { c.sock.destroy(); } catch (e) {} }
            if (/ต่อ port/.test(r.err)) break;          // port ปิด ไม่ต้องลอง Modbus
        }
    }
    return { report };
}

function values(v) {
    const d32 = i => v[i] + v[i + 1] * 65536;
    const total = d32(322), ng = v[60];
    return {
        total, ng, ok: Math.max(0, total - ng),
        rate: d32(330) / 10, ccdNg: d32(300), ccdOk: v[320],
        status: v[0], statusText: { 0: "STOP", 1: "OP", 2: "EG", 3: "SV" }[v[0]] || ("?" + v[0]),
        time: new Date().toLocaleString("en-GB")
    };
}

(async () => {
    try {
        let cfg = context.get("cfg"), v;
        if (!cfg) {
            if (Date.now() < (context.get("retryAt") || 0)) return;
            const d = await discover();
            node.send([null, { topic: "ผลค้นหา " + HOST, payload: d.report }]);
            if (!d.cfg) { node.status({ fill: "red", shape: "ring", text: "หา PLC ไม่เจอ ดูผลใน Debug" }); context.set("retryAt", Date.now() + 60000); return; }
            cfg = d.cfg; context.set("cfg", cfg); v = d.v;
        } else {
            let r = await readOnce(cfg);
            if (!r.v) r = await readOnce(cfg);              // ต่อใหม่แล้วลองซ้ำทันที 1 ครั้ง
            if (!r.v) {
                const n = (context.get("fail") || 0) + 1; context.set("fail", n);
                node.status({ fill: "red", shape: "ring", text: cfg.proto + ":" + cfg.port + " " + r.err + " (" + n + ")" });
                if (n >= 40) { context.set("cfg", null); context.set("fail", 0); }   // พังเกิน ~2 นาที -> ค้นหาใหม่
                return;
            }
            v = r.v;
        }
        context.set("fail", 0);
        const out = values(v);

        // ---- CT (วินาที/ชิ้น) จาก Counter ที่เพิ่มขึ้นในช่วง 60 วินาทีล่าสุด ----
        const WIN = 60000, now = Date.now();
        let hist = (context.get("hist") || []).filter(h => now - h.t <= WIN * 2);
        const last = hist[hist.length - 1];
        if (last && out.total < last.c) hist = [];
        hist.push({ t: now, c: out.total });
        context.set("hist", hist);
        const base = hist.find(h => now - h.t <= WIN) || hist[0];
        const dC = out.total - base.c, dT = (now - base.t) / 1000;
        if (dC > 0 && dT >= 10) {
            out.ct = Math.round(dT / dC * 100) / 100;
            out.pcsPerMin = Math.round(dC / dT * 60 * 10) / 10;
            context.set("lastCt", out.ct);
        } else {
            out.ct = dT >= 10 ? null : (context.get("lastCt") != null ? context.get("lastCt") : null);
            out.pcsPerMin = dT >= 10 ? 0 : null;
        }
        flow.set("sb01", out); flow.set("sb01_ok", Date.now());
        node.status({ fill: "green", shape: "dot", text: cfg.proto + ":" + cfg.port + " | " + out.statusText + " Total " + out.total + " NG " + out.ng + " CT " + (out.ct != null ? out.ct : "-") + "s" });
        node.send([{ topic: "SB01", payload: out }, null]);
    } catch (e) {
        node.status({ fill: "red", shape: "ring", text: String(e.message || e) });
        node.send([null, { topic: "error", payload: String(e.stack || e) }]);
    } finally {
        context.set("busy", false);
    }
})();
return null;

finalize:
// ปิดการเชื่อมต่อเมื่อ Deploy / หยุด flow
const c = context.get("conn"); if (c && c.sock) { try { c.sock.destroy(); } catch (e) {} }
context.set("conn", null); context.set("busy", false);

