// ส่งข้อมูล SB01 ไป Dashboard (CounterMachine.aspx)
const MACHINE = "SB01";            // หน้าเว็บแสดงเป็น "Seambuffing 1"
const PROCESS = "Seambuffing";
const IDEAL_CT = 1.2;              // *** CT มาตรฐาน (วินาที/ชิ้น) ใช้คิด Performance -> แก้ให้ตรงมาตรฐานจริง ***
const d = flow.get("sb01");
const online = !!d && Date.now() - (flow.get("sb01_ok") || 0) < 20000;

if (online) {
    // สถานะเครื่อง: ดูจาก Counter ที่วิ่ง (D0 ไม่ได้บอกว่าเครื่องเดิน)
    //   Counter เพิ่มภายใน RUN_HOLD วินาที -> 4 Running
    //   D0 = 2 (EG) และ Counter ไม่เพิ่ม   -> 18 Breakdown
    //   อื่นๆ                              -> 1 Idle
    const RUN_HOLD = 30;
    const prev = flow.get("sb01_prevTotal");
    if (prev == null || d.total !== prev) {
        if (prev != null && d.total > prev) flow.set("sb01_lastRun", Date.now());
        flow.set("sb01_prevTotal", d.total);
    }
    const running = Date.now() - (flow.get("sb01_lastRun") || 0) < RUN_HOLD * 1000;
    const status = running ? 4 : (d.status === 2 ? 18 : 1);
    d.statusText = running ? "RUN" : (d.status === 2 ? "EG" : "STOP");
    msg.payload = {
        machine: MACHINE, process: PROCESS, online: true, power: "ON",
        status, statusText: d.statusText,
        shotCount: d.total,          // 入球總數 D322
        okCount: d.ok,               // total - ng
        ngCount: d.ng,               // D60
        cycleTime: (d.ct != null ? d.ct : null),     // วินาที/ชิ้น (คำนวณ)
        speedPerMin: (d.pcsPerMin != null ? d.pcsPerMin : null),
        cavities: 1,
        idealCycleTime: IDEAL_CT,
        positioningRate: d.rate,     // 定位率 % D330
        ccdOk: d.ccdOk, ccdNg: d.ccdNg,
        ts: new Date().toISOString()
    };
} else {
    msg.payload = { machine: MACHINE, process: PROCESS, online: false, power: "OFF", ts: new Date().toISOString() };
}
msg.headers = { "Content-Type": "application/json" };
msg.requestTimeout = 4000;
node.status({ fill: online ? "green" : "grey", shape: "dot", text: online ? d.statusText + " " + d.total : "offline" });
return msg;
